// persistent: highCount (int, default 0), signalLow (float), minLowSinceSignal (float)
if (close[0] > highest(high, resetLookback)[1]) {
    highCount = 0; // pullback over, trend made a fresh high
} else {
    minLowSinceSignal = min(minLowSinceSignal, low[0]);
    if (high[0] > high[1]) {
        if (highCount == 0 || minLowSinceSignal < signalLow) {
            highCount = min(highCount + 1, 4);
            signalLow = low[0];
            minLowSinceSignal = low[0];
        }
        // else: a higher-high bar occurred but no new low has formed since the
        // last counted bar -- a retest of the same leg, not a new count
    }
}
